<?php
namespace app\controller;
use app\BaseController;use app\service\AdminAccess;use app\service\GatewayCache;use think\facade\Db;use think\facade\Session;use think\facade\View;
class Keys extends BaseController{
 private function guard(){return AdminAccess::guard();}
 private function log($action,$id,$detail=''){Db::name('audit_logs')->insert(['admin_id'=>Session::get('lumen_admin_id'),'action'=>$action,'target_type'=>'api_key','target_id'=>(int)$id,'detail'=>$detail,'ip'=>request()->ip(),'created_at'=>date('Y-m-d H:i:s')]);}
 public function index(){if($r=$this->guard())return $r;View::assign('items',Db::name('keys')->alias('k')->leftJoin('users u','u.id=k.user_id')->leftJoin('admins a','a.id=k.admin_id')->field('k.*,u.username user_username,a.username admin_username,a.role admin_role')->order('k.id','desc')->select()->toArray());View::assign('username',Session::get('lumen_admin_username'));View::assign('newKey',Session::pull('lumen_new_api_key',''));return View::fetch(root_path().'view/admin/keys.html');}
 public function create(){if($r=$this->guard())return $r;$name=trim((string)input('post.name',''));if($name===''||mb_strlen($name)>100)return response('名称不合法',422);$raw='lmn_'.bin2hex(random_bytes(24));$now=date('Y-m-d H:i:s');$id=Db::name('keys')->insertGetId(['user_id'=>null,'admin_id'=>(int)Session::get('lumen_admin_id'),'name'=>$name,'key_prefix'=>substr($raw,0,12),'key_hash'=>hash('sha256',$raw),'status'=>1,'quota_total'=>null,'quota_used'=>0,'created_at'=>$now,'updated_at'=>$now]);$this->log('api_key.create',$id,$name);Session::set('lumen_new_api_key',$raw);return redirect('/admin/keys');}
 public function toggle($id){if($r=$this->guard())return $r;$id=(int)$id;$x=Db::name('keys')->where('id',$id)->find();if(!$x)return response('Not Found',404);$now=date('Y-m-d H:i:s');if($x['status']){$reason=trim((string)input('post.reason',''));if($reason===''||mb_strlen($reason)<2)return response('管理员封禁必须填写封禁原因',422);if(mb_strlen($reason)>500)return response('封禁原因过长',422);Db::name('keys')->where('id',$id)->update(['status'=>0,'ban_source'=>'admin','ban_reason'=>$reason,'banned_at'=>$now,'updated_at'=>$now]);GatewayCache::forgetKeyHash((string)$x['key_hash']);$this->log('api_key.ban',$id,'source=admin; reason='.$reason);}else{$old='source='.($x['ban_source']?:'unknown').'; reason='.($x['ban_reason']?:'-');Db::name('keys')->where('id',$id)->update(['status'=>1,'ban_source'=>null,'ban_reason'=>null,'banned_at'=>null,'updated_at'=>$now]);GatewayCache::forgetKeyHash((string)$x['key_hash']);$this->log('api_key.unban',$id,$old);}return redirect('/admin/keys');}
 public function quota($id){if($r=$this->guard())return $r;$op=(string)input('post.op','');$amount=filter_var(input('post.amount'),FILTER_VALIDATE_INT);if($amount===false||$amount<0)return response('额度必须是非负整数',422);$id=(int)$id;$x=Db::name('keys')->where('id',$id)->find();if(!$x)return response('Not Found',404);Db::transaction(function()use($id,$op,$amount,$x){$row=Db::name('keys')->where('id',$id)->lock(true)->find();$total=$row['quota_total']===null?null:(int)$row['quota_total'];if($op==='set')$total=$amount;elseif($op==='add')$total=($total??0)+$amount;elseif($op==='sub')$total=max(0,($total??0)-$amount);elseif($op==='unlimited')$total=null;elseif($op==='reset_used'){Db::name('keys')->where('id',$id)->update(['quota_used'=>0,'updated_at'=>date('Y-m-d H:i:s')]);return;}else throw new \InvalidArgumentException('bad op');Db::name('keys')->where('id',$id)->update(['quota_total'=>$total,'updated_at'=>date('Y-m-d H:i:s')]);});GatewayCache::forgetKeyHash((string)$x['key_hash']);$this->log('api_key.quota_'.$op,$id,'amount='.$amount);return redirect('/admin/keys');}
}
